import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.BTLSZHNB.js";const k=JSON.parse('{"title":"Exact Interface contracts (interfaces.takoform.com/v1alpha1)","description":"","frontmatter":{},"headers":[],"relativePath":"spec/interface-contract/index.md","filePath":"spec/interface-contract/index.md"}'),n={name:"spec/interface-contract/index.md"};function o(r,e,h,c,d,l){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="exact-interface-contracts-interfaces-takoform-com-v1alpha1" tabindex="-1">Exact Interface contracts (interfaces.takoform.com/v1alpha1) <a class="header-anchor" href="#exact-interface-contracts-interfaces-takoform-com-v1alpha1" aria-label="Permalink to &quot;Exact Interface contracts (interfaces.takoform.com/v1alpha1)&quot;">​</a></h1><p>An Interface is a digest-bound contract for one portable operation surface, distributed with this repository. It replaces the open <code>(name, version, operations)</code> descriptors of the retained v1alpha2 lane for all new-lane Forms (<a href="./../decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). It is not an independently published artifact: see <a href="#interface-distribution">Interface distribution</a> below for exactly what an InterfaceRef does and does not assure (<a href="./../decisions/0021-third-party-forms-and-contract-distribution.html">decision 0021</a>). The retained projection contract remains documented in <a href="./../interface-declaration/"><code>../interface-declaration/</code></a> for the frozen lanes.</p><h2 id="interfaceref" tabindex="-1">InterfaceRef <a class="header-anchor" href="#interfaceref" aria-label="Permalink to &quot;InterfaceRef&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;interfaces.takoform.com/v1alpha1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edge.kv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaDigest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>name</code> uses the dotted grammar <code>^[a-z][a-z0-9]*(?:\\.[a-z][a-z0-9]*)*$</code> (max 128). Segments are lowercase alphanumeric; a hyphen is invalid here, so an Interface name never mirrors a hyphenated Binding name such as <code>module-worker.service</code>. The Edge Platform Family&#39;s worker-scoped contracts are therefore <code>worker.service</code> and <code>worker.runtime</code>.</li><li><code>version</code> is SemVer.</li><li><code>schemaDigest</code> is the RFC 8785 canonical digest of the Interface Definition bytes. Two definitions with different canonical bytes are different Interfaces even under one display name.</li></ul><p>The normative shape is <a href="/schemas/interfaces/v1alpha1/interface-ref.schema.json"><code>../schemas/interface-ref-v1alpha1.schema.json</code></a>.</p><h2 id="interface-definition" tabindex="-1">Interface Definition <a class="header-anchor" href="#interface-definition" aria-label="Permalink to &quot;Interface Definition&quot;">​</a></h2><p>The normative shape is <a href="/schemas/interfaces/v1alpha1/interface-definition.schema.json"><code>../schemas/interface-definition-v1alpha1.schema.json</code></a>. A definition MUST fix, as data only:</p><ul><li><code>operations[]</code>: name, input schema, output schema, and a closed <code>errors[]</code> vocabulary per operation;</li><li><code>semantics</code>: the consistency model and pagination contract the whole surface obeys — closed enums, not free tokens.</li></ul><p>A definition SHOULD also declare, and MAY omit (both fields are OPTIONAL in the schema, and the schema wins per <a href="./../conformance.html"><code>../conformance.md</code></a>):</p><ul><li><code>limits</code>: portable minimum limits every conforming host MUST accept when the definition declares them;</li><li><code>fixtures[]</code>: declarative behavior traces (see below).</li></ul><p>A definition MUST NOT contain executable code, credentials, endpoints, prices, or host identities; the Form Package data-only policy applies unchanged.</p><p>Rules that are behavioral rather than structural — what an uncaught exception does, whether a body streams, what keeps an isolate alive — are stated as normative sentences in the definition&#39;s own <code>description</code> and per-operation <code>description</code>, and proven by fixtures wherever a fixture can prove them. That is the placement rule of <a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a>: the published meta-schema is a structural minimum, so a contract expresses everything it can within what that schema already admits rather than minting a new identity for each new kind of rule. <code>worker.runtime@1.0.0</code> is the worked example (<a href="./../decisions/0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a>).</p><h2 id="runtime-abis-are-interfaces-too" tabindex="-1">Runtime ABIs are Interfaces too <a class="header-anchor" href="#runtime-abis-are-interfaces-too" aria-label="Permalink to &quot;Runtime ABIs are Interfaces too&quot;">​</a></h2><p>An Interface is not only a capability a resource offers outward. The exact runtime a host provides to code it runs is the same kind of contract, and is declared the same way: <code>ModuleWorker</code> lists <code>worker.runtime@1.0.0</code> in its <code>providedInterfaces</code>, a host that supports that Form implements the contract at that exact digest, and a runtime revision is a new contract version rather than a new value of some field. A Form MUST NOT state a runtime by a version token, date, or flag whose meaning depends on a registry the specification does not publish.</p><p>A runtime contract is verified in two places, and neither substitutes for the other. The Host API conformance lane drives desired state, so it proves what a host SAYS and what it REFUSES: the exact advertised digest, the closed handler vocabulary, and that a Worker Version declaring a handler the ABI does not define — or one the module it references does not export — is refused before anything is stored. Everything the contract fixes about invocation is proven by its behavior fixtures against a real isolate: handler signatures, streaming bodies, <code>env</code>&#39;s exact property set, <code>waitUntil</code>, exception outcomes, and the <code>globals</code> floor. The exact split for <code>worker.runtime@1.0.0</code> is written down in <a href="./../host-api/v1alpha3.html#what-the-lane-proves-and-what-stays-a-host-obligation"><code>../host-api/v1alpha3.md</code></a>, because a reader deciding whether a passing conformance report means &quot;this host runs my code correctly&quot; is entitled to know which half it covers.</p><h2 id="behavior-fixtures" tabindex="-1">Behavior fixtures <a class="header-anchor" href="#behavior-fixtures" aria-label="Permalink to &quot;Behavior fixtures&quot;">​</a></h2><p>Shape validation alone cannot distinguish a KV store from a queue, so an Interface Definition SHOULD carry data-only traces:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;put-then-get&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;steps&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;operation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;put&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;input&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AQID&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;operation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;get&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;input&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;expected&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;found&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A conforming implementation executes each trace in order against one fresh scope and MUST produce outputs matching every <code>expected</code> clause. Properties that are not deterministically observable from one client (for example cross-location convergence of an eventually consistent store) are out of fixture scope and belong to distributed conformance runs, not packages.</p><h2 id="interface-distribution" tabindex="-1">Interface distribution <a class="header-anchor" href="#interface-distribution" aria-label="Permalink to &quot;Interface distribution&quot;">​</a></h2><p>Interface Definitions are distributed <strong>with this repository</strong>, as digest-bound documents under <code>interfaces/candidates/v1alpha1</code>. They are NOT independently installable third-party artifacts, and there is no Interface Package envelope: no such identity is specified, published, or planned for this generation (<a href="./../decisions/0021-third-party-forms-and-contract-distribution.html">decision 0021</a>).</p><p>What an exact InterfaceRef therefore assures, and what it does not:</p><ul><li><code>schemaDigest</code> binds the RFC 8785 canonical Definition bytes, so a holder of those bytes MUST be able to confirm they are the document the ref names, and two different canonical byte strings are two different Interfaces;</li><li>the ref says nothing about where the bytes came from. There is no package digest, no publisher identity, no signature, no transparency proof, no revocation statement, and no closed payload inventory, because there is no package. The Form Package trust lane (<a href="./../trust/"><code>../trust/</code></a>) covers Form Packages only.</li></ul><p>A host obtains these contracts the way it obtains any other part of this specification. An operator who installs an Interface Definition from any other source has exactly the assurance they arranged for it themselves; this specification provides none and MUST NOT be read as providing any.</p><p>Building the envelope means minting a <code>packages.interfaces.takoform.com</code> index identity, which cannot be done by reusing <a href="/schemas/v1alpha4/package-index.schema.json"><code>../schemas/package-index-v1alpha4.schema.json</code></a>: that index is closed, fixes <code>kind</code> to <code>FormPackage</code>, and requires a <code>formRef</code>. The mint therefore waits for the next coherent generation of schema identities (<a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a>).</p><h2 id="relationship-to-forms-and-bindings" tabindex="-1">Relationship to Forms and Bindings <a class="header-anchor" href="#relationship-to-forms-and-bindings" aria-label="Permalink to &quot;Relationship to Forms and Bindings&quot;">​</a></h2><ul><li>A Form Definition lists the Interfaces its resources provide as exact <code>providedInterfaces[]</code> refs.</li><li>A Binding contract names the Interface its target must provide as an exact ref; a host resolving a binding MUST verify the target Form provides that Interface.</li><li>Hosts advertise which Interfaces they implement, and within which limits, in their Host Support Profile — never inside the Interface Definition.</li></ul>`,28)])])}const f=a(n,[["render",o]]);export{k as __pageData,f as default};
